  "labs/workflow-plugin/workflows/schedule-proposal.json": "{\n  \"state\": \"prepared-not-scheduled\",\n  \"work\": \"Summarize a manually selected fictional README fixture.\",\n  \"cadence\": \"Weekdays at 09:00\",\n  \"timezone\": \"Asia/Bangkok\",\n  \"environment\": \"Local scratch project with existing Node; actual scheduling requires the supported app.\",\n  \"scope\": \"Read bundled fixtures only; do not send, publish, or edit.\",\n  \"notification\": \"Notify on meaningful findings, failure, or required input; remain quiet only after a successful no-change check.\",\n  \"approval\": \"Obtain affirmative approval of this exact cadence, timezone, project, and action before creation.\"\n}\n\n",
