const byModule = new Map(definitions.map(activity => [activity.moduleId, activity]));
const byId = new Map(definitions.map(activity => [activity.id, activity]));
const normalize = value => typeof value === 'string' ? value.trim().replace(/\s+/g, ' ').toLowerCase() : '';

function matches(rule, value) {
  if (typeof value !== 'string' || value.length > 2000) return false;
  if (rule.tokens) {
    const tokens = normalize(value).split(/[\s,;]+/).filter(Boolean);
    return tokens.length === rule.tokens.length && new Set(tokens).size === tokens.length && rule.tokens.every(token => tokens.includes(token));
  }
  if (rule.numbers) {
    const tokens = value.trim().split(/[\s,;]+/).filter(Boolean);
    return tokens.length === rule.numbers.length && tokens.every((token, index) => /^\d+$/.test(token) && Number(token) === rule.numbers[index]);
  }
  if (rule.caseSensitive) return value.trim().replace(/\s+/g, ' ') === rule.value;
  return normalize(value) === normalize(rule.value);
}

export function getActivity(moduleId) {
  const activity = byModule.get(String(moduleId).padStart(2, '0'));
  return activity ? clone({...activity, evidenceLabel: 'Browser practice · supplied sources', isModulePractice: true, states: ['inspect', 'attempt', 'compare'], boundary: BOUNDARY}) : null;
}

export function evaluateActivity(activityId, attempt) {
  const activity = byId.get(activityId);
  if (!activity) throw new RangeError('Unknown guided activity: ' + String(activityId));
  const supplied = attempt && typeof attempt === 'object' && !Array.isArray(attempt) ? attempt : {};
  const items = activity.questions.map(question => {
    const passed = matches(answers[activityId][question.id], Object.hasOwn(supplied, question.id) ? supplied[question.id] : undefined);
    return {id: question.id, passed, message: passed ? 'Your answer matches the supplied source evidence.' : 'Reopen the source: ' + question.sourceHint};
  });
  const count = items.filter(item => item.passed).length;
  return {passed: count === items.length, items, summary: `${count} of ${items.length} source checks match. Browser practice only; lesson completion remains your choice.`};
}

// The caller must offer this as an explicit reveal; it is never applied to an attempt.
export function getActivityReference(activityId) {
  const activity = byId.get(activityId);
  if (!activity) throw new RangeError('Unknown guided activity: ' + String(activityId));
  return {
    summary: 'Authored reference derived from the supplied files. ' + BOUNDARY,
    answers: activity.questions.map(question => {
      const rule = answers[activityId][question.id];
      return {id: question.id, label: question.label, value: rule.value, display: question.options?.find(option => option.value === rule.value)?.label || rule.value, explanation: rule.explanation};
    })
  };
}

export const activityIds = Object.freeze(definitions.map(activity => activity.id));
